          },
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You set a clear timeline instead of deciding on weak evidence.",
              "example": "You told the manager 'let's check again in six months.'"
            }
          ],
          "next": "ending-cautious"
        }
      ]
    },
    {
