          "replies": [
            {
              "from": "manager",
              "text": "That's simpler. The standard has worked fine, and we avoid the hassle."
            },
            {
              "from": "icn",
              "text": "Reasonable, but we might miss a real improvement."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "confidence",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
